"""Real DOM test for the offline distributable; separate empty browser profile."""
import re,shutil,subprocess,sys,tempfile
from pathlib import Path
JS='''<script>try{const one=q=>document.querySelector(q),all=q=>Array.from(document.querySelectorAll(q)),ok=(v,m)=>{if(!v)throw Error(m)},tap=q=>{const b=one(q);ok(b,'missing '+q);b.click()},act=k=>tap('[data-a="'+k+'"]'),navT=k=>tap('[data-k="'+k+'"]');let total=0,slots=0;ok(one('.intro')&&!one('.choice'),'first screen is intro');for(const lg of ['ru','uk']){tap('[data-lang="'+lg+'"]');for(let i=0;i<3;i++){tap('[data-a="lesson"][data-i="'+i+'"]');ok(one('#mast').textContent.includes('ES-0'+(i+4)),'wrong display ordinal');act('nextIntro');act('nextIntro');act('launch');navT('verb');ok(all('.forms .card').length===[6,12,10][i],'incomplete tables');navT('words');ok(all('.lex .card').length===lessons[i].vocabulary.new.length+lessons[i].vocabulary.seenBefore.length,'lost fresh or revisited cards');navT('theory');ok(all('#body details').length===7,'missing theory');for(let j=0;j<50;j++){navT('bank');ok(all('.bank-item').length===50,'missing phrases');tap('[data-a="run"][data-i="'+j+'"]');const p=lessons[i].phrases[j];ok(one('#prompt').textContent===p.prompt[lg],'bad prompt '+p.id);ok(!one('#target'),'visible answer');if(p.context[lg])ok(one('#body').textContent.includes(p.context[lg]),'missing context');for(let k=0;k<p.practiceWords.length;k++){const w=p.practiceWords[k];let b=all('.choice button');ok(b.length===6,'count '+p.id);if(k===0){b.find(x=>x.textContent!==w.correct).click();ok(st().slot===0&&one('[role="status"]').textContent,'incorrect advanced');b=all('.choice button')}if(j%10===0&&k===1){act('why');act('back');ok(st().slot===k&&st().idx===j,'lost place');b=all('.choice button')}b.find(x=>x.textContent===w.correct).click();slots++}ok(one('#target').textContent===p.targetText,'bad punctuation/answer '+p.id);act('explain');ok(one('#body details')&&one('#body').textContent.includes(p.analysis.operation[lg]),'bad analysis');act('back');total++}ok(st().done.length===50,'completion');act('next');ok(tab==='summary','summary');}}ok(total===300&&slots===2*lessons.flatMap(l=>l.phrases).reduce((n,p)=>n+p.practiceWords.length,0),'totals');document.body.dataset.proof=total+':'+slots;}catch(err){document.body.dataset.err=err.stack||err.message;}</script>'''
def main(p):
    exe=next((shutil.which(x) for x in ['google-chrome','chromium','chromium-browser'] if shutil.which(x)),None);assert exe,'No Chromium';src=p.read_text('utf8');
    with tempfile.TemporaryDirectory() as td:
        f=Path(td)/'review.html';f.write_text(src.replace('</html>',JS+'</html>',1),'utf8');r=subprocess.run([exe,'--headless','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--disable-background-networking',f'--user-data-dir={td}/profile','--dump-dom',f.as_uri()],capture_output=True,timeout=160);body=r.stdout.split(b'<body',1)[-1].split(b'>',1)[0];assert r.returncode==0 and b'data-proof="300:' in body,(body[:2048],r.stderr[-400:]);print('Chromium PASS (complete phrase journeys:word selections): '+body.decode().strip());
if __name__=='__main__':main(Path(sys.argv[1]).resolve())
